composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      KAUI_CONFIG_DAO_URL: "jdbc:mysql://{{serviceName}}-mysql:3306/kaui"
      KAUI_CONFIG_DAO_USERNAME: kaui
      KAUI_CONFIG_DAO_PASSWORD: {{env.KAUI_CONFIG_DAO_PASSWORD}}
      KAUI_KILLBILL_API_KEY: {{env.KAUI_KILLBILL_API_KEY}}
      KAUI_KILLBILL_API_SECRET: {{env.KAUI_KILLBILL_API_SECRET}}
      KAUI_KILLBILL_URL: {{env.KAUI_KILLBILL_URL}}
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: kaui
      MYSQL_USER: kaui
      MYSQL_PASSWORD: {{env.KAUI_CONFIG_DAO_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.KAUI_CONFIG_DAO_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
